"""Isolated PostgreSQL15.19 via official binaries and direct libpq, no package install."""
import ctypes,os,pathlib,shutil,signal,socket,subprocess,tempfile,time
PREFIX=pathlib.Path('/opt/opsforge-postgres')
class DatabaseError(Exception):
    def __init__(self,state,message):self.state=state;self.message=message;super().__init__(state+': '+message)
class Postgres:
    def __enter__(self):
        self.temp=tempfile.TemporaryDirectory(prefix='of-pg-');self.root=pathlib.Path(self.temp.name);self.root.chmod(0o700);self.process=None;self.connection=None;self.log=None
        try:
            self.bin=PREFIX/'usr/lib/postgresql/15/bin'
            version=subprocess.check_output([str(self.bin/'postgres'),'--version'],text=True,timeout=3)
            if '15.19' not in version:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: official PostgreSQL15.19 required')
            init=subprocess.run([str(self.bin/'initdb'),'-D',str(self.root/'data'),'-L',str(PREFIX/'usr/share/postgresql/15'),'--no-locale','--encoding=UTF8','-A','trust','-U','lab','--no-sync'],capture_output=True,text=True,timeout=15)
            if init.returncode:raise RuntimeError('private initdb failed: '+init.stderr[-1500:])
            with socket.socket() as endpoint:endpoint.bind(('127.0.0.1',0));self.port=endpoint.getsockname()[1]
            with (self.root/'data/postgresql.conf').open('a') as out:
                out.write("\nlisten_addresses=''\nunix_socket_directories='"+str(self.root)+"'\nport="+str(self.port)+"\nshared_buffers='8MB'\nmax_connections=50\nmax_worker_processes=4\nmax_parallel_workers=4\ndynamic_shared_memory_type=posix\nmin_dynamic_shared_memory=0\njit=off\nhuge_pages=off\nfsync=off\nfull_page_writes=off\nlog_min_messages=error\n")
            self.log=(self.root/'postgres.log').open('wb');self.process=subprocess.Popen([str(self.bin/'postgres'),'-D',str(self.root/'data')],stdout=self.log,stderr=self.log,start_new_session=True)
            library=ctypes.CDLL('/usr/lib/x86_64-linux-gnu/libpq.so.5');self.lib=library
            for name,restype,argtypes in [('PQconnectdb',ctypes.c_void_p,[ctypes.c_char_p]),('PQstatus',ctypes.c_int,[ctypes.c_void_p]),('PQerrorMessage',ctypes.c_char_p,[ctypes.c_void_p]),('PQfinish',None,[ctypes.c_void_p]),('PQexec',ctypes.c_void_p,[ctypes.c_void_p,ctypes.c_char_p]),('PQresultStatus',ctypes.c_int,[ctypes.c_void_p]),('PQresultErrorMessage',ctypes.c_char_p,[ctypes.c_void_p]),('PQresultErrorField',ctypes.c_char_p,[ctypes.c_void_p,ctypes.c_int]),('PQntuples',ctypes.c_int,[ctypes.c_void_p]),('PQnfields',ctypes.c_int,[ctypes.c_void_p]),('PQgetvalue',ctypes.c_char_p,[ctypes.c_void_p,ctypes.c_int,ctypes.c_int]),('PQgetisnull',ctypes.c_int,[ctypes.c_void_p,ctypes.c_int,ctypes.c_int]),('PQclear',None,[ctypes.c_void_p])]:
                function=getattr(library,name);function.restype=restype;function.argtypes=argtypes
            deadline=time.monotonic()+6
            while time.monotonic()<deadline:
                if self.process.poll() is not None:raise RuntimeError('private server exited: '+(self.root/'postgres.log').read_text(errors='replace')[-1500:])
                connection=library.PQconnectdb(('host='+str(self.root)+' port='+str(self.port)+' user=lab dbname=postgres connect_timeout=1').encode())
                if library.PQstatus(connection)==0:self.connection=connection;break
                library.PQfinish(connection);time.sleep(.03)
            else:raise RuntimeError('private PostgreSQL readiness deadline')
            print('NATIVE_POSTGRESQL_READY:15.19',flush=True);return self
        except BaseException:self.__exit__(None,None,None);raise
    def execute(self,sql):
        result=self.lib.PQexec(self.connection,sql.encode())
        if not result:raise RuntimeError('native libpq query returned no result')
        try:
            if self.lib.PQresultStatus(result) not in (1,2):
                state=self.lib.PQresultErrorField(result,67) or b'UNKNOWN';message=self.lib.PQresultErrorMessage(result) or b''
                raise DatabaseError(state.decode(),message.decode(errors='replace'))
            rows,fields=self.lib.PQntuples(result),self.lib.PQnfields(result)
            if rows>1000 or fields>64:raise RuntimeError('bounded PostgreSQL result exceeded')
            return [[None if self.lib.PQgetisnull(result,row,col) else self.lib.PQgetvalue(result,row,col).decode() for col in range(fields)] for row in range(rows)]
        finally:self.lib.PQclear(result)
    def __exit__(self,*args):
        if self.connection is not None:self.lib.PQfinish(self.connection);self.connection=None
        if self.process is not None and self.process.poll() is None:
            # SIGINT is the documented fast shutdown; only this private postmaster.
            self.process.send_signal(signal.SIGINT)
            try:self.process.wait(timeout=5)
            except subprocess.TimeoutExpired:os.killpg(self.process.pid,signal.SIGKILL);self.process.wait(timeout=2)
        if self.log:self.log.close()
        self.temp.cleanup()

